import sys
from collections import defaultdict

def find_schedule(n, m, exams):
    # Dictionary to store available days for preparation and exams
    available_days = defaultdict(list)
    # List to store the schedule
    schedule = [0] * n

    # Populate available days for preparation and exams
    for i in range(m):
        start, end, prep_days = exams[i]
        for day in range(start, end):
            available_days[day].append(i + 1)

    # Try to assign days for preparation and exams
    for day in range(1, n + 1):
        if day in available_days:
            # If it's exam day, mark it as such
            schedule[day - 1] = available_days[day][0]
        elif available_days:
            # Otherwise, find a preparation day
            exam_index = available_days[available_days.keys()[0]][0]
            if len(schedule) >= exam_index + prep_days - 1:
                # Prepare for the exam in the next prep_days days
                for j in range(exam_index, exam_index + prep_days):
                    if schedule[j - 1] == 0:
                        schedule[j - 1] = exam_index
                    else:
                        return [-1]  # Conflict detected

    # Check if all exams are prepared for and passed
    for i in range(m):
        exam_index = i + 1
        found = False
        for j in range(n):
            if schedule[j] == exam_index:
                if j >= exams[i][0] - 1 and j <= exams[i][1] - 2:
                    continue
                else:
                    return [-1]  # Invalid exam day
        if not found:
            return [-1]  # Exam not found

    return schedule

