import sys

def main():
    input = sys.stdin.read
    data = input().split()

    index = 0
    n = int(data[index])
    m = int(data[index + 1])
    index += 2

    exams = []
    for _ in range(m):
        s = int(data[index])
        d = int(data[index + 1])
        c = int(data[index + 2])
        index += 3
        exams.append((s, d, c))

    days = [0] * n

    for i in range(n):
        for s, d, c in exams:
            if s <= i < d and days[i] == 0:
                if days.count(0) >= c:
                    days[i] = i + 1
                    c -= 1

        if sum(days) != len([x for x in days if x != 0]):
            return [-1]

        if c > 0:
            for j in range(n):
                if days[j] == 0:
                    days[j] = i + 1
                    c -= 1
                    break

        if c > 0:
            return [-1]

    return days

if __name__ == "__main__":
    result = main()
    if isinstance(result, list) and result[0] == -1:
        print(-1)
    else:
        print(" ".join(map(str, result)))
